def render_scoreboard(rows, width=36):
    if not isinstance(rows, tuple):
        raise TypeError("rows must be a tuple")
    if type(width) is not int:
        raise TypeError("width must be an integer")
    if width < 20:
        raise ValueError("width must be at least 20")

    lines = ["=" * width, "SCOREBOARD".center(width)]
    for row in rows:
        if not isinstance(row, tuple):
            raise TypeError("each row must be a tuple")
        if len(row) != 2:
            raise ValueError("each row must contain two items")
        label, score = row
        if not isinstance(label, str):
            raise TypeError("labels must be strings")
        if not label or "\n" in label or "\r" in label:
            raise ValueError("labels must be non-empty single-line strings")
        if type(score) is not int:
            raise TypeError("scores must be integers")
        if score < 0:
            raise ValueError("scores must be non-negative")
        score_text = str(score)
        dot_count = width - len(label) - len(score_text)
        if dot_count < 2:
            raise ValueError("row does not fit the selected width")
        lines.append(label + " " * dot_count + score_text)
    lines.append("=" * width)
    return "\n".join(lines)

